function depositAndSend(
        uint256 _underlyingAmount,
        SendParam memory _sendParam,
        address _refundAddress
    )
        public
        payable
        virtual
        override
        nonReentrant
        whenFactoryNotPaused
        returns (
            MessagingReceipt memory msgReceipt,
            OFTReceipt memory oftReceipt
        )
    {
        VaultComposerSyncStorage storage $ = _getVaultComposerSyncStorage();
        IERC20($.underlyingToken).safeTransferFrom(
            msg.sender,
            address(this),
            _underlyingAmount
        );
        IUnderlyingOFT($.underlyingOft).deposit(_underlyingAmount);

        (msgReceipt, oftReceipt) = _depositAndSend(
            OFTComposeMsgCodec.addressToBytes32(msg.sender),
            _underlyingAmount,
            _sendParam,
            _refundAddress
        );
        if (_sendParam.oftCmd.length == 32) {
            emit ReferralInfo(
                msg.sender,
                abi.decode(_sendParam.oftCmd, (bytes32)),
                oftReceipt.amountSentLD
            );
        }
    }

function redeemAndSend(
        uint256 _shareAmount,
        SendParam memory _sendParam,
        address _refundAddress
    ) external payable override nonReentrant whenFactoryNotPaused {
        VaultComposerSyncStorage storage $ = _getVaultComposerSyncStorage();
        VaultComposerStorage storage $$ = _getVaultComposerStorage();

        MessagingFee memory fee;
        if (_sendParam.dstEid != $.localEid) {
            fee = quoteSend(
                msg.sender,
                $.underlyingOft,
                _shareAmount,
                _sendParam
            );

            if (msg.value < fee.nativeFee)
                revert Errors.NotEnoughValueToPayFees();
        } else {
            if (msg.value != 0) revert Errors.FeeNonZero();
        }

        ComposerWithdrawalQueueEntry memory entry;
        entry.initiator = msg.sender;
        entry.shareAmount = _shareAmount;
        entry.sendParam = _sendParam;
        entry.fee = fee.nativeFee;
        entry.txFee = msg.value - fee.nativeFee;
        entry.refundAddress = _refundAddress;

        IERC20(address($.vault)).safeTransferFrom(
            msg.sender,
            address(this),
            _shareAmount
        );

        uint256 id = $$.withdrawalQueue.length;
        $$.withdrawalQueue.push(entry);
        emit WithdrawalRequest(id, msg.sender, block.timestamp);
    }

function _depositAndSend(
        bytes32 _depositor,
        uint256 _underlyingAmount,
        SendParam memory _sendParam,
        address _refundAddress
    )
        internal
        virtual
        returns (MessagingReceipt memory receipt, OFTReceipt memory oftReceipt)
    {
        VaultComposerSyncStorage storage $ = _getVaultComposerSyncStorage();
        uint256 shareAmount = _deposit(_depositor, _underlyingAmount);
        _assertSlippage(shareAmount, _sendParam.minAmountLD);

        _sendParam.amountLD = shareAmount;
        _sendParam.minAmountLD = 0;

        (receipt, oftReceipt) = _send(
            address($.vault),
            _sendParam,
            _refundAddress,
            msg.value
        );

        emit Deposited(
            _depositor,
            _sendParam.to,
            _sendParam.dstEid,
            _underlyingAmount,
            shareAmount
        );
    }

function _send(
        address _oft,
        SendParam memory _sendParam,
        address _refundAddress,
        uint256 _nativeFee
    )
        internal
        returns (MessagingReceipt memory receipt, OFTReceipt memory oftReceipt)
    {
        VaultComposerSyncStorage storage $ = _getVaultComposerSyncStorage();
        if (_sendParam.dstEid == $.localEid) {
            /// @dev Can do this because _oft is validated before this function is called
            if (_nativeFee > 0) revert NoMsgValueExpected();
            if ($.underlyingOft == _oft) {
                IUnderlyingOFT($.underlyingOft).withdraw(_sendParam.amountLD);
                IERC20($.underlyingToken).safeTransfer(
                    _sendParam.to.bytes32ToAddress(),
                    _sendParam.amountLD
                );
            } else {
                IERC20(_oft).safeTransfer(
                    _sendParam.to.bytes32ToAddress(),
                    _sendParam.amountLD
                );
            }

            oftReceipt = OFTReceipt({
                amountSentLD: _sendParam.amountLD,
                amountReceivedLD: _sendParam.amountLD
            });
        } else {
            // crosschain send
            return
                IOFT(_oft).send{ value: _nativeFee }(
                    _sendParam,
                    MessagingFee(_nativeFee, 0),
                    _refundAddress
                );
        }
    }

function executeLiquidationCall(
    mapping(address => DataTypes.ReserveData) storage reservesData,
    mapping(uint256 => address) storage reservesList,
    mapping(address => DataTypes.UserConfigurationMap) storage usersConfig,
    mapping(uint8 => DataTypes.EModeCategory) storage eModeCategories,
    DataTypes.ExecuteLiquidationCallParams memory params
  ) external {
    LiquidationCallLocalVars memory vars;

    DataTypes.ReserveData storage collateralReserve = reservesData[params.collateralAsset];
    DataTypes.ReserveData storage debtReserve = reservesData[params.debtAsset];
    DataTypes.UserConfigurationMap storage userConfig = usersConfig[params.user];
    vars.debtReserveCache = debtReserve.cache();
    debtReserve.updateState(vars.debtReserveCache);

    (, , , , vars.healthFactor, ) = GenericLogic.calculateUserAccountData(
      reservesData,
      reservesList,
      eModeCategories,
      DataTypes.CalculateUserAccountDataParams({
        userConfig: userConfig,
        reservesCount: params.reservesCount,
        user: params.user,
        oracle: params.priceOracle,
        userEModeCategory: params.userEModeCategory
      })
    );

    (vars.userVariableDebt, vars.userTotalDebt, vars.actualDebtToLiquidate) = _calculateDebt(
      vars.debtReserveCache,
      params,
      vars.healthFactor
    );

    ValidationLogic.validateLiquidationCall(
      userConfig,
      collateralReserve,
      DataTypes.ValidateLiquidationCallParams({
        debtReserveCache: vars.debtReserveCache,
        totalDebt: vars.userTotalDebt,
        healthFactor: vars.healthFactor,
        priceOracleSentinel: params.priceOracleSentinel
      })
    );

    (
      vars.collateralAToken,
      vars.collateralPriceSource,
      vars.debtPriceSource,
      vars.liquidationBonus
    ) = _getConfigurationData(eModeCategories, collateralReserve, params);

    vars.userCollateralBalance = vars.collateralAToken.balanceOf(params.user);

    (
      vars.actualCollateralToLiquidate,
      vars.actualDebtToLiquidate,
      vars.liquidationProtocolFeeAmount
    ) = _calculateAvailableCollateralToLiquidate(
      collateralReserve,
      vars.debtReserveCache,
      vars.collateralPriceSource,
      vars.debtPriceSource,
      vars.actualDebtToLiquidate,
      vars.userCollateralBalance,
      vars.liquidationBonus,
      IPriceOracleGetter(params.priceOracle)
    );

    if (vars.userTotalDebt == vars.actualDebtToLiquidate) {
      userConfig.setBorrowing(debtReserve.id, false);
    }

    // If the collateral being liquidated is equal to the user balance,
    // we set the currency as not being used as collateral anymore
    if (
      vars.actualCollateralToLiquidate + vars.liquidationProtocolFeeAmount ==
      vars.userCollateralBalance
    ) {
      userConfig.setUsingAsCollateral(collateralReserve.id, false);
      emit ReserveUsedAsCollateralDisabled(params.collateralAsset, params.user);
    }

    _burnDebtTokens(params, vars);

    debtReserve.updateInterestRates(
      vars.debtReserveCache,
      params.debtAsset,
      vars.actualDebtToLiquidate,
      0
    );

    IsolationModeLogic.updateIsolatedDebtIfIsolated(
      reservesData,
      reservesList,
      userConfig,
      vars.debtReserveCache,
      vars.actualDebtToLiquidate
    );

    if (params.receiveAToken) {
      _liquidateATokens(reservesData, reservesList, usersConfig, collateralReserve, params, vars);
    } else {
      _burnCollateralATokens(collateralReserve, params, vars);
    }

    // Transfer fee to treasury if it is non-zero
    if (vars.liquidationProtocolFeeAmount != 0) {
      uint256 liquidityIndex = collateralReserve.getNormalizedIncome();
      uint256 scaledDownLiquidationProtocolFee = vars.liquidationProtocolFeeAmount.rayDiv(
        liquidityIndex
      );
      uint256 scaledDownUserBalance = vars.collateralAToken.scaledBalanceOf(params.user);
      // To avoid trying to send more aTokens than available on balance, due to 1 wei imprecision
      if (scaledDownLiquidationProtocolFee > scaledDownUserBalance) {
        vars.liquidationProtocolFeeAmount = scaledDownUserBalance.rayMul(liquidityIndex);
      }
      vars.collateralAToken.transferOnLiquidation(
        params.user,
        vars.collateralAToken.RESERVE_TREASURY_ADDRESS(),
        vars.liquidationProtocolFeeAmount
      );
    }

    // Transfers the debt asset being repaid to the aToken, where the liquidity is kept
    IERC20(params.debtAsset).safeTransferFrom(
      msg.sender,
      vars.debtReserveCache.aTokenAddress,
      vars.actualDebtToLiquidate
    );

    IAToken(vars.debtReserveCache.aTokenAddress).handleRepayment(
      msg.sender,
      params.user,
      vars.actualDebtToLiquidate
    );

    emit LiquidationCall(
      params.collateralAsset,
      params.debtAsset,
      params.user,
      vars.actualDebtToLiquidate,
      vars.actualCollateralToLiquidate,
      msg.sender,
      params.receiveAToken
    );
  }

function _calculateDebt(
    DataTypes.ReserveCache memory debtReserveCache,
    DataTypes.ExecuteLiquidationCallParams memory params,
    uint256 healthFactor
  ) internal view returns (uint256, uint256, uint256) {
    (uint256 userStableDebt, uint256 userVariableDebt) = Helpers.getUserCurrentDebt(
      params.user,
      debtReserveCache
    );

    uint256 userTotalDebt = userStableDebt + userVariableDebt;

    uint256 closeFactor = healthFactor > CLOSE_FACTOR_HF_THRESHOLD
      ? DEFAULT_LIQUIDATION_CLOSE_FACTOR
      : MAX_LIQUIDATION_CLOSE_FACTOR;

    uint256 maxLiquidatableDebt = userTotalDebt.percentMul(closeFactor);

    uint256 actualDebtToLiquidate = params.debtToCover > maxLiquidatableDebt
      ? maxLiquidatableDebt
      : params.debtToCover;

    return (userVariableDebt, userTotalDebt, actualDebtToLiquidate);
  }

function _liquidateATokens(
    mapping(address => DataTypes.ReserveData) storage reservesData,
    mapping(uint256 => address) storage reservesList,
    mapping(address => DataTypes.UserConfigurationMap) storage usersConfig,
    DataTypes.ReserveData storage collateralReserve,
    DataTypes.ExecuteLiquidationCallParams memory params,
    LiquidationCallLocalVars memory vars
  ) internal {
    uint256 liquidatorPreviousATokenBalance = IERC20(vars.collateralAToken).balanceOf(msg.sender);
    vars.collateralAToken.transferOnLiquidation(
      params.user,
      msg.sender,
      vars.actualCollateralToLiquidate
    );

    if (liquidatorPreviousATokenBalance == 0) {
      DataTypes.UserConfigurationMap storage liquidatorConfig = usersConfig[msg.sender];
      if (
        ValidationLogic.validateAutomaticUseAsCollateral(
          reservesData,
          reservesList,
          liquidatorConfig,
          collateralReserve.configuration,
          collateralReserve.aTokenAddress
        )
      ) {
        liquidatorConfig.setUsingAsCollateral(collateralReserve.id, true);
        emit ReserveUsedAsCollateralEnabled(params.collateralAsset, msg.sender);
      }
    }
  }

function _burnCollateralATokens(
    DataTypes.ReserveData storage collateralReserve,
    DataTypes.ExecuteLiquidationCallParams memory params,
    LiquidationCallLocalVars memory vars
  ) internal {
    DataTypes.ReserveCache memory collateralReserveCache = collateralReserve.cache();
    collateralReserve.updateState(collateralReserveCache);
    collateralReserve.updateInterestRates(
      collateralReserveCache,
      params.collateralAsset,
      0,
      vars.actualCollateralToLiquidate
    );

    // Burn the equivalent amount of aToken, sending the underlying to the liquidator
    vars.collateralAToken.burn(
      params.user,
      msg.sender,
      vars.actualCollateralToLiquidate,
      collateralReserveCache.nextLiquidityIndex
    );
  }

function validateLiquidationCall(
    DataTypes.UserConfigurationMap storage userConfig,
    DataTypes.ReserveData storage collateralReserve,
    DataTypes.ValidateLiquidationCallParams memory params
  ) internal view {
    ValidateLiquidationCallLocalVars memory vars;

    (vars.collateralReserveActive, , , , vars.collateralReservePaused) = collateralReserve
      .configuration
      .getFlags();

    (vars.principalReserveActive, , , , vars.principalReservePaused) = params
      .debtReserveCache
      .reserveConfiguration
      .getFlags();

    require(vars.collateralReserveActive && vars.principalReserveActive, Errors.RESERVE_INACTIVE);
    require(!vars.collateralReservePaused && !vars.principalReservePaused, Errors.RESERVE_PAUSED);

    require(
      params.priceOracleSentinel == address(0) ||
        params.healthFactor < MINIMUM_HEALTH_FACTOR_LIQUIDATION_THRESHOLD ||
        IPriceOracleSentinel(params.priceOracleSentinel).isLiquidationAllowed(),
      Errors.PRICE_ORACLE_SENTINEL_CHECK_FAILED
    );

    require(
      params.healthFactor < HEALTH_FACTOR_LIQUIDATION_THRESHOLD,
      Errors.HEALTH_FACTOR_NOT_BELOW_THRESHOLD
    );

    vars.isCollateralEnabled =
      collateralReserve.configuration.getLiquidationThreshold() != 0 &&
      userConfig.isUsingAsCollateral(collateralReserve.id);

    //if collateral isn't enabled as collateral by user, it cannot be liquidated
    require(vars.isCollateralEnabled, Errors.COLLATERAL_CANNOT_BE_LIQUIDATED);
    require(params.totalDebt != 0, Errors.SPECIFIED_CURRENCY_NOT_BORROWED_BY_USER);
  }

function liquidationCall(
    address collateralAsset,
    address debtAsset,
    address user,
    uint256 debtToCover,
    bool receiveAToken
  ) public virtual override {
    LiquidationLogic.executeLiquidationCall(
      _reserves,
      _reservesList,
      _usersConfig,
      _eModeCategories,
      DataTypes.ExecuteLiquidationCallParams({
        reservesCount: _reservesCount,
        debtToCover: debtToCover,
        collateralAsset: collateralAsset,
        debtAsset: debtAsset,
        user: user,
        receiveAToken: receiveAToken,
        priceOracle: ADDRESSES_PROVIDER.getPriceOracle(),
        userEModeCategory: _usersEModeCategory[user],
        priceOracleSentinel: ADDRESSES_PROVIDER.getPriceOracleSentinel()
      })
    );
  }

function claimAssets(uint256 requestId)
        external
        override
        nonReentrant
        sanctionsCheck
        whitelistCheck
        returns (uint256)
    {
        AsyncRedeemerStorage storage $ = _getAsyncRedeemerStorage();

        address receiver = ownerOf(requestId);

        if (msg.sender != receiver) {
            revert IERC721Errors.ERC721IncorrectOwner(msg.sender, requestId, receiver);
        }

        uint256 assets = getClaimableAssets(requestId);
        uint256 shares = $._requests[requestId].shares;

        _burn(requestId);
        delete $._requests[requestId];

        IERC20(IMachine(machine()).accountingToken()).safeTransfer(receiver, assets);

        emit RedeemRequestClaimed(requestId, shares, assets, receiver);

        return assets;
    }

function requestRedeemWithFulfil(uint256 shares) external returns (uint256 requestId) {
        setOperator(address(this), true);
        return _requestRedeem(shares, _msgSender(), _msgSender(), _msgSender());
    }

function setOperator(address operator, bool approved) public returns (bool) {
        _getStorage().operators[_msgSender()][operator] = approved;
        emit OperatorSet(_msgSender(), operator, approved);
        return true;
    }

function _requestRedeem(uint256 shares, address controller, address owner, address caller)
        internal returns (uint256 requestId)
    {
        LiquidityHubStorage storage $ = _getStorage();
        bool ownerOrOperator = caller == owner || isOperator(owner, caller);
        if (!ownerOrOperator) {
            _spendAllowance(owner, caller, shares);
        }
        _burn(owner, shares);
        $.redeemRequests[controller] += shares;
        $.totalRedeemRequest += shares;
        emit RedeemRequest(controller, owner, 0, caller, shares);
        return 0;
    }

function cancelRedeem(address receiver) external requiresAuth whenNotPaused {
        PendingRedeem storage pending = _pendingRedeem[receiver];
        uint256 shares = pending.shares;
        require(shares != 0, Errors.InvalidSharesAmount());
        uint256 reservedAssets = pending.assets;

        delete _pendingRedeem[receiver];
        totalPendingAssets -= reservedAssets;

        emit RequestCancelled(receiver, shares, reservedAssets);
        // return the escrowed shares to the receiver
        _transfer(address(this), receiver, shares);
    }

function requestRedeem(uint256 shares, address receiver, address owner) public whenNotPaused returns (uint256) {
        require(receiver != address(0), Errors.ZeroReceiver());
        require(receiver != address(this), Errors.SelfReceiverNotAllowed());
        require(shares > 0, Errors.SharesAmountZero());
        require(owner == msg.sender, Errors.NotSharesOwner());
        require(balanceOf(owner) >= shares, Errors.InsufficientShares());

        uint256 assetsWithFee = super.previewRedeem(shares);

        // instant redeem if the vault has enough assets
        if (_getAvailableBalance() >= assetsWithFee) {
            _withdraw(owner, receiver, owner, assetsWithFee, shares);
            emit RedeemRequest(receiver, owner, assetsWithFee, shares, true);
            return assetsWithFee;
        }

        emit RedeemRequest(receiver, owner, assetsWithFee, shares, false);
        // transfer the shares to the vault and store the request
        _transfer(owner, address(this), shares);

        totalPendingAssets += assetsWithFee;
        PendingRedeem storage pending = _pendingRedeem[receiver];
        pending.shares += shares;
        pending.assets += assetsWithFee;

        return REQUEST_ID;
    }

function isAuthorized(address user, bytes4 functionSig) public view virtual returns (bool) {
        AuthStorage storage $ = _getAuthStorage();
        IAuthority auth = $.authority;
        return (address(auth) != address(0) && auth.canCall(user, address(this), functionSig)) || user == $.owner;
    }

